import {calculate,breakdown} from './calculate.mjs';
import {filterLibrary,productOf,restoreView} from './library.mjs';
import {inspectPDF,repeatPDF,projectToPDF} from './pdf-tools.mjs';
const $=id=>document.getElementById(id),num=n=>new Intl.NumberFormat('zh-CN').format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let previewMode='single';
let records=[],selected=null,draft=null,result=null,busy=false,selectionRevision=0,toastTimer,catalogAudit=null;
let view;try{view=restoreView(localStorage.getItem('label-quantity-view'));}catch{view=restoreView(null);}
function rememberView(){try{localStorage.setItem('label-quantity-view',JSON.stringify({id:selected?.id||'',quantity:Number($('quantity').value),product:$('productFilter').value,group:$('groupFilter').value,query:$('search').value}));}catch{}}
const db=new Promise((resolve,reject)=>{const req=indexedDB.open('label-quantity-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('labels',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
async function store(mode,action){const database=await db;return new Promise((resolve,reject)=>{const tx=database.transaction('labels',mode),req=action(tx.objectStore('labels'));let value;req.onsuccess=()=>{value=req.result;};tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('保存被中断'));});}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6500);}
function paper(record){const w=record.paperW,h=record.paperH;if(!w||!h)return 'A4';const a=Math.min(w,h),b=Math.max(w,h);const type=Math.abs(a-210)<1&&Math.abs(b-297)<1?'A4':Math.abs(a-297)<1&&Math.abs(b-420)<1?'A3':`${w.toFixed(1)} × ${h.toFixed(1)} mm`;return `${type} ${w>h?'横向':'纵向'}`;}
function renderLibrary(){
  const product=$('productFilter').value,group=$('groupFilter').value;
  const products=[...new Set(records.map(productOf))];
  $('productFilter').replaceChildren(new Option(`全部产品 · ${records.length}`,''),...products.map(p=>new Option(`${p} · ${records.filter(r=>productOf(r)===p).length}`,p)));
  $('productFilter').value=products.includes(product)?product:'';
  const subset=filterLibrary(records,{product:$('productFilter').value}),groups=[...new Set(subset.map(r=>r.group||'我的标签'))];
  $('groupFilter').replaceChildren(new Option('全部包装 / 版式',''),...groups.map(g=>new Option(`${g} · ${subset.filter(r=>(r.group||'我的标签')===g).length}`,g)));
  $('groupFilter').value=groups.includes(group)?group:'';
  const visible=filterLibrary(records,{query:$('search').value,product:$('productFilter').value,group:$('groupFilter').value});
  $('libraryCount').textContent=records.length;$('filterSummary').textContent=`找到 ${visible.length} 款${visible.length!==records.length?` / 全部 ${records.length} 款`:''}`;
  $('libraryList').innerHTML=visible.length?visible.map(r=>`<button class="label-card ${r.id===selected?.id?'active':''}" data-id="${esc(r.id)}" role="listitem" aria-label="选择 ${esc(r.name)}" aria-pressed="${r.id===selected?.id}"><div class="label-thumb ${(r.singleThumbnail||r.singlePreview)?'label-thumb-single':'label-thumb-sheet'}">${(r.singleThumbnail||r.singlePreview||r.preview||r.thumbnail)?`<img src="${esc(r.singleThumbnail||r.singlePreview||r.preview||r.thumbnail)}" alt="" loading="lazy">`:'<span class="mini-grid" aria-hidden="true"></span>'}</div><div><h3>${esc(r.name)}</h3><p>${esc(r.group||'我的标签')}</p><span class="capacity">${num(r.cols*r.rows)} 枚 / 纸</span>${r.custom?'<span class="personal-tag">个人保存</span>':''}</div>${r.id===selected?.id?'<span class="selected-dot">●</span>':''}</button>`).join(''):'<p class="empty">没有找到这款标签<br>试试其他名称，或切换产品和包装分类。</p>';
  for(const card of $('libraryList').querySelectorAll('[data-id]'))card.onclick=()=>select(card.dataset.id);
}
function renderResult(){result=null;let error='';if(!selected)error='先选择或导入一款标签。';else try{result=calculate(Number($('quantity').value),selected.cols,selected.rows);}catch(e){error=e.message;}
  $('quantityError').hidden=!error;$('quantityError').textContent=error;
  $('sheets').textContent=result?num(result.sheets):'—';$('breakdown').textContent=result?breakdown(result):'输入有效数量后自动计算';
  for(const key of ['capacity','produced','surplus'])$(key).textContent=result?num(result[key]):'—';
  $('printLabel').textContent=result?`打印 ${num(result.sheets)} 张纸`:'打印整版标签';
  for(const id of ['print'])$(id).disabled=busy||!result||!selected?.bytes||result.sheets>500;
  if(result?.sheets>500){$('quantityError').hidden=false;$('quantityError').textContent='用纸量已算出；单次最多生成500页，请减少本次数量后分批打印。';}
  for(const btn of document.querySelectorAll('[data-quantity]'))btn.classList.toggle('active',+btn.dataset.quantity===Number($('quantity').value));
}
function renderSelected(){if(!selected)return;const r=selected;$('selectedName').textContent=r.name;$('selectedMeta').textContent=`${paper(r)} · 每行 ${r.cols} 枚 · 共 ${r.rows} 行 · 每纸 ${r.cols*r.rows} 枚${r.pages>1?` · 使用第${r.page||1}/${r.pages}页`:''}`;$('sourceNote').hidden=!r.sourceNote;$('sourceNote').textContent=r.sourceNote||'';renderPreview();renderLibrary();renderResult();}
function renderPreview(){if(!selected)return;const r=selected,single=previewMode==='single'&&!!r.singlePreview;
 $('singleMode').disabled=!r.singlePreview;$('singleMode').setAttribute('aria-pressed',String(single));$('sheetMode').setAttribute('aria-pressed',String(!single));
 $('previewTitle').textContent=single?'单标签预览':'整版预览';$('previewPaper').textContent=single?'单枚':paper(r);$('previewSummary').textContent=single?r.name:`${r.cols}列 × ${r.rows}行，共${r.cols*r.rows}枚`;
 $('previewNote').textContent=single?'打印仍使用原整版文件':(r.singlePreview?'全部纸张使用相同版面':'此标签尚未提供单标签预览');
 $('sheetDimensions').textContent=single?`单标签 ${r.labelW} × ${r.labelH} mm`:(r.paperW?`纸张 ${r.paperW.toFixed(1)} × ${r.paperH.toFixed(1)} mm · 原尺寸`:'正在读取纸张尺寸');
 const src=single?r.singlePreview:r.preview;if(src)$('sheetImage').src=src;else $('sheetImage').removeAttribute('src');$('sheetImage').alt=single?'当前单标签预览':'当前整版标签预览';$('sheetImage').classList.toggle('single-label',single);
}
async function ensurePDF(r,preview=true){if(!r.bytes){const url=new URL(r.url,import.meta.url);if(r.sha256)url.searchParams.set('v',r.sha256);const response=await fetch(url,{cache:'no-cache'});if(!response.ok)throw Error('标签文件加载失败。');r.bytes=new Uint8Array(await response.arrayBuffer());}if(!(r.bytes instanceof Uint8Array))r.bytes=new Uint8Array(r.bytes);if(preview&&!r.preview&&(!r.singlePreview||previewMode==='sheet')){Object.assign(r,await inspectPDF(r.bytes,r.page||1));}return r;}
async function select(id){const rev=++selectionRevision,r=records.find(v=>v.id===id);if(!r)return;selected=r;renderSelected();rememberView();try{await ensurePDF(r);if(rev===selectionRevision)renderSelected();}catch(e){if(rev===selectionRevision){toast(e.message);$('quantityError').textContent='标签文件暂时无法读取，请重新导入。';$('quantityError').hidden=false;for(const id of ['print'])$(id).disabled=true;}}}
function download(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function output(print){if(!result||busy)return;const snapshot={...result},record=selected;busy=true;renderResult();$('printLabel').textContent='正在准备整版文件…';try{await ensurePDF(record);const bytes=await repeatPDF(record.bytes,record.page||1,snapshot.sheets),name=`${record.name.replace(/[\\/:*?"<>|]/g,'_')}_${snapshot.sheets}张纸.pdf`;if(!print){download(bytes,name,'application/pdf');toast(`已生成${snapshot.sheets}页相同整版，打印请选择1份、实际大小100%。`);}else{
      const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),frame=document.createElement('iframe');frame.title='标签打印文件';frame.style.cssText='position:fixed;right:0;bottom:0;width:1px;height:1px;opacity:0;pointer-events:none';frame.src=url;frame.onload=()=>{try{frame.contentWindow.focus();frame.contentWindow.print();toast(`已准备${snapshot.sheets}页。打印窗口选1份、实际大小100%。`);}catch{download(bytes,name,'application/pdf');toast('浏览器未能直接打印，已下载PDF。请打开后按1份、实际大小100%打印。');}};document.body.append(frame);setTimeout(()=>{frame.remove();URL.revokeObjectURL(url);},300000);
    }}catch(e){toast('生成失败：'+e.message);}finally{busy=false;renderResult();}}
function validateRecord(r){if(!r||typeof r.name!=='string'||!r.name.trim()||r.name.length>100||typeof r.group!=='string'||r.group.length>80||!Number.isSafeInteger(r.cols)||!Number.isSafeInteger(r.rows)||r.cols<1||r.rows<1||r.cols>1000||r.rows>1000||!Number.isSafeInteger(r.page)||r.page<1)throw Error('标签名称或行列参数无效。');return r;}
function edit(record,isNew=false){draft={...record,isNew};$('editTitle').textContent=isNew?'保存到我的标签':'修改标签参数';$('editName').value=record.name;$('editGroup').value=record.group||'';$('editCols').value=record.cols||'';$('editRows').value=record.rows||'';$('editPage').replaceChildren(...Array.from({length:record.pages||1},(_,i)=>new Option(`第 ${i+1} 页 / 共 ${record.pages||1} 页`,String(i+1))));$('editPage').value=record.page||1;$('editPage').disabled=record.pages===1;$('editInfo').textContent=`${paper(record)} · ${record.inferred?'已从中文总数识别行列，保存前请核对。':'请填写整版中每行的标签枚数及总行数。'} 文件内容保持原样，不重新排版。`;$('editError').hidden=true;$('deleteLabel').hidden=isNew||!record.custom;$('editDialog').showModal();}
async function importFile(file){if(!file)return;try{if(file.size>300*1024*1024)throw Error('文件过大，标签库备份最大300MB。');let bytes,params={},name=file.name.replace(/\.(pdf|ai|json)$/i,'');
    if(/\.json$/i.test(file.name)){const project=JSON.parse(await file.text());if(project.app==='label-quantity-studio'){await restoreObject(project);return;}if(file.size>100*1024*1024)throw Error('尺切工程最大100MB。');const converted=await projectToPDF(project);bytes=converted.bytes;params={cols:converted.cols,rows:converted.rows};name=project.source.name.replace(/\.[^.]+$/,'');}
    else{if(file.size>30*1024*1024)throw Error('PDF文件最大30MB。');bytes=new Uint8Array(await file.arrayBuffer());}
    const info=await inspectPDF(bytes);edit({id:'user_'+crypto.randomUUID(),name,group:'我的标签',bytes,page:1,...info,...(info.inferred||{}),...params},true);
  }catch(e){toast('导入失败：'+e.message);}finally{$('file').value='';}}
function encode64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);}
function decode64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
async function backup(){try{$('backup').disabled=true;toast('正在打包标签库，请稍候…');const labels=[];for(const r of records){await ensurePDF(r,false);labels.push({id:r.id,name:r.name,group:r.group,cols:r.cols,rows:r.rows,page:r.page||1,pdf:encode64(r.bytes)});}download(JSON.stringify({app:'label-quantity-studio',version:1,labels},null,2),'标签用量助手_标签库备份.json','application/json');toast('标签库备份已导出，包含整版PDF和打印参数。');}catch(e){toast('备份失败：'+e.message);}finally{$('backup').disabled=false;}}
async function restoreObject(data){if(data.app!=='label-quantity-studio'||data.version!==1||!Array.isArray(data.labels)||data.labels.length>500)throw Error('备份格式无效，最多支持500款标签。');const incoming=[];for(const item of data.labels){validateRecord(item);if(typeof item.pdf!=='string'||item.pdf.length>42*1024*1024)throw Error('备份中的PDF数据无效或过大。');const bytes=decode64(item.pdf);if(bytes.length>30*1024*1024)throw Error('备份中的PDF超过30MB。');const info=await inspectPDF(bytes,item.page);incoming.push({...item,id:'user_'+crypto.randomUUID(),bytes,...info,custom:true});delete incoming.at(-1).pdf;}
  const database=await db;await new Promise((resolve,reject)=>{const tx=database.transaction('labels','readwrite');for(const r of incoming)tx.objectStore('labels').put(r);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});records.push(...incoming);$('search').value='';$('groupFilter').value='';renderLibrary();$('productFilter').value='我的标签';renderLibrary();if(incoming[0])await select(incoming[0].id);toast(`已恢复${incoming.length}款标签，原标签库保留。`);}
$('quantity').oninput=()=>{renderResult();rememberView();};document.querySelectorAll('[data-quantity]').forEach(btn=>btn.onclick=()=>{$('quantity').value=btn.dataset.quantity;renderResult();rememberView();});$('increase').onclick=()=>{$('quantity').value=Math.max(1,(Number($('quantity').value)||0)+100);renderResult();rememberView();};$('decrease').onclick=()=>{$('quantity').value=Math.max(1,(Number($('quantity').value)||1)-100);renderResult();rememberView();};$('search').oninput=()=>{renderLibrary();rememberView();};$('groupFilter').onchange=()=>{renderLibrary();rememberView();};$('productFilter').onchange=()=>{$('groupFilter').value='';renderLibrary();rememberView();};
$('print').onclick=()=>output(true);$('settings').onclick=async()=>{if(selected)try{await ensurePDF(selected);edit(selected);}catch(e){toast(e.message);}};
$('import').onclick=$('addLabel').onclick=()=>$('file').click();$('file').onchange=e=>importFile(e.target.files[0]);$('closeEdit').onclick=()=>$('editDialog').close();
$('editPage').onchange=async()=>{if(!draft)return;try{const info=await inspectPDF(draft.bytes,+$('editPage').value);Object.assign(draft,info,{page:+$('editPage').value});if(info.inferred){$('editCols').value=info.inferred.cols;$('editRows').value=info.inferred.rows;}$('editInfo').textContent=`${paper(draft)} · 当前为第${draft.page}页，请核对本页行列数。`;}catch(e){$('editError').hidden=false;$('editError').textContent=e.message;}};
$('editForm').onsubmit=async e=>{e.preventDefault();if(!draft)return;$('saveLabel').disabled=true;try{const r={...draft,name:$('editName').value.trim(),group:$('editGroup').value.trim(),cols:Number($('editCols').value),rows:Number($('editRows').value),page:Number($('editPage').value),custom:true};delete r.isNew;validateRecord(r);await inspectPDF(r.bytes,r.page);await store('readwrite',s=>s.put(r));const index=records.findIndex(v=>v.id===r.id);if(index<0)records.push(r);else records[index]=r;if(draft.isNew){$('search').value='';$('groupFilter').value='';renderLibrary();$('productFilter').value=productOf(r);}$('editDialog').close();await select(r.id);toast('已保存到本机标签库，下次可以直接选择。');}catch(e){$('editError').hidden=false;$('editError').textContent='保存失败：'+e.message;}finally{$('saveLabel').disabled=false;}};
$('deleteLabel').onclick=async()=>{if(!draft?.custom)return;try{await store('readwrite',s=>s.delete(draft.id));records=records.filter(r=>r.id!==draft.id);$('editDialog').close();const visible=filterLibrary(records,{query:$('search').value,product:$('productFilter').value,group:$('groupFilter').value});if(records[0]){if(!visible[0]){$('search').value='';$('productFilter').value='';$('groupFilter').value='';}await select((visible[0]||records[0]).id);}else{selected=null;renderLibrary();renderResult();$('selectedName').textContent='请选择或导入标签';}toast('已从本机标签库移除，原始PDF文件不受影响。');}catch(e){toast(e.message);}};
$('backup').onclick=backup;$('restore').onclick=()=>$('backupFile').click();$('backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>300*1024*1024)throw Error('备份最大300MB。');await restoreObject(JSON.parse(await file.text()));}catch(e){toast('恢复失败：'+e.message);}finally{$('backupFile').value='';}};
$('singleMode').onclick=()=>{previewMode='single';renderPreview();};$('sheetMode').onclick=async()=>{previewMode='sheet';const r=selected;renderPreview();try{await ensurePDF(r);if(selected===r)renderPreview();}catch(e){toast(e.message);}};
$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('preview').ontoggle=()=>$('preview').querySelector('.preview-toggle').textContent=$('preview').open?'收起 −':'展开 ＋';
async function loadCatalogAudit(){try{const response=await fetch(new URL('./samples/catalog-audit.json',import.meta.url),{cache:'no-cache'});if(!response.ok)throw Error('盘点清单未找到');catalogAudit=await response.json();$('catalogStatus').textContent=`${catalogAudit.scannedAt} · ${catalogAudit.ready} 款`;$('catalogSummary').textContent=`${catalogAudit.scannedAt} 盘点 · ${catalogAudit.files} 个文件 · ${catalogAudit.groups.length} 个分类。当前已收录 ${catalogAudit.ready} 个整版模板。`;$('catalogGroups').innerHTML=catalogAudit.groups.map(g=>`<div><span>${esc(g.group)}</span><strong>${g.ready} 个模板</strong></div>`).join('');$('catalogIssues').innerHTML=catalogAudit.issues.map(x=>`<div class="catalog-issue"><strong>${esc(x.source)}</strong><p>${esc(x.note)}</p></div>`).join('');$('catalogNotes').innerHTML=catalogAudit.notes.map(n=>`<li>${esc(n)}</li>`).join('');$('openCloud').hidden=true;}catch{$('catalogStatus').textContent='本机标签库';$('catalogSummary').textContent='盘点清单暂时无法读取，请稍后重试。';}}
$('catalogDetails').onclick=async()=>{if(!catalogAudit)await loadCatalogAudit();$('catalogDialog').showModal();};$('closeCatalog').onclick=()=>$('catalogDialog').close();
async function init(){loadCatalogAudit();try{const manifest=await(await fetch(new URL('./samples/index.json',import.meta.url),{cache:'no-cache'})).json();records=manifest;try{const saved=await store('readonly',s=>s.getAll());const merged=new Map(records.map(r=>[r.id,r]));for(const r of saved)merged.set(r.id,r);records=[...merged.values()];}catch{toast('浏览器未允许本机存储，仍可计算；标签保存暂不可用。');}renderLibrary();$('quantity').value=view.quantity;$('search').value=view.query;renderLibrary();$('productFilter').value=view.product;renderLibrary();$('groupFilter').value=view.group;renderLibrary();if(records[0])await select(records.some(r=>r.id===view.id)?view.id:records[0].id);else{$('selectedName').textContent='先导入一款整版标签';$('selectedMeta').textContent='选择已有整版 PDF 或尺切工程，保存后即可计算用量。';renderResult();}}catch(e){toast('标签库加载失败：'+e.message);renderResult();}}
init();
